  ('dvwa-lab-notes', 'What I learned attacking DVWA', 'Notes from testing every module in Damn Vulnerable Web Application, and what each one taught me about writing safer code.', '/img/projects/cyber-lab.webp', array['Security', 'DVWA', 'Web']::text[], 'This is a draft. Write your post here in Markdown, then switch on Published in the admin panel and press Publish.

## SQL injection

![SQL injection module](/img/projects/dvwa-01.webp)

## Stored XSS

![Stored XSS module](/img/projects/dvwa-02.webp)', false, '2026-10-27'::date)
) as v(slug, title, excerpt, cover_url, tags, body, published, published_on)
where not exists (select 1 from public.posts);

